import { useEffect, useRef } from 'react';
import { toast } from 'sonner';
import { publicUrl } from '@/lib/basePath';

export function AppUpdateChecker() {
  const currentVersion = useRef<number | null>(null);

  useEffect(() => {
    const checkVersion = async () => {
      try {
        // Fetch the version.json file generated by Vite on build.
        // We append a timestamp to prevent the browser from caching the response.
        const response = await fetch(`${publicUrl('version.json')}?t=${new Date().getTime()}`, {
          cache: 'no-store'
        });
        
        if (!response.ok) return;
        const data = await response.json();
        
        if (currentVersion.current === null) {
          // On first load, store the current version
          currentVersion.current = data.version;
        } else if (data.version !== currentVersion.current) {
          // If the server's version differs from the running version, a new deployment occurred
          toast.info("A new version of the app is available!", {
            id: 'app-update',
            duration: 100000,
            action: {
              label: 'Update Now',
              onClick: () => window.location.reload(),
            },
          });
        }
      } catch (error) {
        // Ignore errors (e.g. if the user is offline or file doesn't exist in dev)
      }
    };

    // Check immediately on mount
    checkVersion();

    // Check every 5 minutes
    const interval = setInterval(checkVersion, 5 * 60 * 1000);

    // Check whenever the user refocuses the tab
    window.addEventListener('focus', checkVersion);

    // Handle Vite's chunk load error (when a user navigates and the old JS chunk was deleted from server)
    const handlePreloadError = (e: Event) => {
      e.preventDefault();
      // Force reload to get the new index.html and new chunks
      window.location.reload();
    };
    window.addEventListener('vite:preloadError', handlePreloadError);

    return () => {
      clearInterval(interval);
      window.removeEventListener('focus', checkVersion);
      window.removeEventListener('vite:preloadError', handlePreloadError);
    };
  }, []);

  return null;
}
